    char *argv[] = {"x", "y", "exam", "prep", "engine"};
    char **ptr[] = {argv + 3, argv + 2, argv + 1, argv};
    char ***p = ptr;
    p++;
    printf("%s %s", **p, *(*p + 1) + 1);
    return 0;
}
```

